import{_ as n,l as r,o as e,c as l,v as o,p as i,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"索洛模型","description":"","frontmatter":{"title":"索洛模型","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/solow-growth.md","filePath":"econ/solow-growth.md","lastUpdated":1789023840000}'),h={name:"econ/solow-growth.md"};function E(A,a,f,g,_,k){const s=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="索洛模型" tabindex="-1">索洛模型 <a class="header-anchor" href="#索洛模型" aria-label="Permalink to &quot;索洛模型&quot;">​</a></h1><div class="epigraph"><p>储蓄率决定稳态资本密度，不决定稳态增长率；人均产出的长期增长要靠外生的技术。</p><footer>—— Solow, A Contribution to the Theory of Economic Growth, QJE 1956</footer></div><p><a href="/econ/beveridge-curve">上一课</a>（贝弗里奇曲线）。在此之上，充分就业钉在自然率与潜在产出 \\(y^*\\) 上。潜在产出仍可以随时间变。本课的缺口不是再分解失业，而是：在劳动力按自然率使用时，资本如何积累，人均产出的水平与增长率各由什么决定。Solow（1956）把储蓄率写成外生，技术写成外生；黄金律与内生增长是后课对这两个外生的缺口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>核算恒等给出 \\(S=I\\)，没有资本的运动定律。若每年把产出的固定比例 \\(s\\) 变成投资，资本存量 \\(K\\) 仍可能被折旧 \\(\\delta\\) 与人口增长 \\(n\\) 摊薄。问题是稳态里人均资本是否收敛、收敛到哪里、那里的增长还剩什么。</p><p>生产用规模报酬不变的 \\(Y=F(K,AL)\\)，\\(A\\) 为劳动增进型技术。人均有效劳动变量 \\(k=K/(AL)\\)。没有 \\(A\\) 的增长，人均产出在稳态停止增长——这是对「提高 \\(s\\) 就能永远加快增长」的拒绝。\\(s\\) 只移动水平。</p><p><span class="marginnote">Solow 1956 与 Swan 1956 同期。本课用 Solow 的连续时间写法。技术 \\(A\\) 在本课是外生；把它当成研发产出是 <a href="/econ/endogenous-growth">Romer</a> 的缺口。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>运动方程</p> \\[\\dot{k}=sf(k)-(n+g+\\delta)k, \\]<p>\\(g=\\dot{A}/A\\)，\\(f(k)=F(k,1)\\)。稳态 \\(\\dot{k}=0\\) 给出 \\(sf(k^*)=(n+g+\\delta)k^*\\)。索洛残差（Solow 1957）把产出增长里不能由 \\(K\\)、\\(L\\) 解释的部分叫技术变化，那是核算，本课模型把 \\(g\\) 直接当作参数。</p>',11)),(e(),i(c,null,{default:t(()=>[p(s,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%A4%96%E7%94%9F%E5%82%A8%E8%93%84%E7%8E%87%20s%22%5D%20--%3E%20KDOT%5B%22k%20%E7%9A%84%E7%A7%AF%E7%B4%AF%22%5D%0A%20%20NG%5B%22n%2Bg%2B%CE%B4%20%E6%91%8A%E8%96%84%22%5D%20--%3E%20KDOT%0A%20%20KDOT%20--%3E%20SS%5B%22%E7%A8%B3%E6%80%81%20k*%22%5D%0A%20%20SS%20--%3E%20LEVEL%5B%22%E6%B0%B4%E5%B9%B3%E6%95%88%E5%BA%94%22%5D%0A%20%20G%5B%22%E5%A4%96%E7%94%9F%20g%22%5D%20--%3E%20GROWTH%5B%22%E4%BA%BA%E5%9D%87%E5%A2%9E%E9%95%BF%20%E2%86%92%20g%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>政策：提高 \\(s\\) 使 \\(k^*\\)、\\(y^*\\) 上升，过渡期增长加快，稳态增长率回到 \\(g\\)。人口增长 \\(n\\) 提高摊薄，压低 \\(k^*\\)。这是比较静态，不是因果计量。</p><h3 id="为何需要-inada-与凹性" tabindex="-1">为何需要 Inada 与凹性 <a class="header-anchor" href="#为何需要-inada-与凹性" aria-label="Permalink to &quot;为何需要 Inada 与凹性&quot;">​</a></h3><p>\\(f\\) 凹、\\(f(0)=0\\)、Inada 条件保证内部稳态唯一、鞍点式的全局收敛（一维无须鞍点，只是单调收敛）。若 \\(f\\) 是 AK，稳态增长由 \\(s\\) 决定——那正是后课内生增长要打开的刀刃。本课保持递减报酬，使 \\(s\\) 不能充当永久增长引擎。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>递减报酬使追加资本的边际产出下降，直到刚好覆盖摊薄。收敛是模型内的：\\(k\\lt k^*\\) 时投资超过摊薄，\\(\\dot{k}\\gt 0\\)。跨国是否收敛，是<a href="/econ/convergence-accounting">发展核算</a>的经验缺口；本课只给出条件：同样的 \\(s,n,g,\\delta,f\\) 才会走到同一 \\(k^*\\)。</p><p>消费 \\(c=(1-s)f(k)\\)。稳态消费未必对 \\(s\\) 单调：太高的 \\(s\\) 把太多产出锁进资本，吃掉消费。哪个 \\(s\\) 使 \\(c^*\\) 最大，是黄金律。本课不优化 \\(s\\)，只把它当参数。</p><p>索洛残差（1957）把增长里不能由 \\(K\\)、\\(L\\) 解释的部分叫技术变化。本课模型把 \\(g\\) 当参数；残差是核算，不是已经识别了研发部门。过渡动态上，提高 \\(s\\) 会加快增长一阵子，然后回到 \\(g\\)——把过渡期增长率当成新的稳态，是最常见的误读。</p><p><span class="marginnote">Inada 与凹性保证内部稳态。若 \\(f\\) 是 AK，稳态增长由 \\(s\\) 决定。那是后课内生增长的刀刃，本课刻意保持递减报酬。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>外生 \\(s\\) 切断了消费的欧拉方程；Ramsey–Cass–Koopmans 会把 \\(s\\) 内生化，但稳态增长仍靠外生 \\(g\\)。本课也不含失业波动：周期对照是 RBC/NK 的课。资本在此是单一 \\(K\\)，不是公司金融里的证券；更不是限价簿。人口增长 \\(n\\) 提高摊薄、压低 \\(k^*\\)，不是「人多必然穷」的因果计量。</p><p>后课默认：谈到「索洛稳态」时，水平由 \\(s\\) 等参数决定，人均增长由 \\(g\\) 决定。下一课问：这个 \\(s\\) 会不会积累过度。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>充分就业路径上，资本按 \\(s\\) 积累、按 \\(n+g+\\delta\\) 摊薄。</li><li>\\(s\\) 有水平效应，稳态人均增长等于外生 \\(g\\)。</li><li>递减报酬使稳态存在；过渡期增长加快不等于稳态 \\(g\\) 变了。</li><li>黄金律选择 \\(s\\)，内生增长解释 \\(g\\)。</li><li>出处：Solow, QJE 1956；技术变化核算见 Solow 1957。</li></ul>',13))])}const B=n(h,[["render",E]]);export{u as __pageData,B as default};
